// Fungsi yang akan dianalisis
function hitungDiskon(harga, member, kodPromo) {
  let diskon = 0;

  if (member === true) {          // Keputusan 1
    diskon += 10;
  }

  if (kodPromo === 'SAVE20') {    // Keputusan 2
    diskon += 20;
  } else if (kodPromo === 'VIP') { // Keputusan 3
    diskon += 30;
  }

  if (harga > 500_000) {          // Keputusan 4
    diskon += 5;
  }

  return harga * (1 - diskon / 100);
}

// ANALISIS CYCLOMATIC COMPLEXITY:
// V(G) = Jumlah Keputusan + 1
// V(G) = 4 keputusan + 1 = 5

// Artinya: Butuh MINIMAL 5 test case untuk cover semua path:
// Path 1: member=false, promo=null,    harga=100.000  → diskon 0%
// Path 2: member=true,  promo=null,    harga=100.000  → diskon 10%
// Path 3: member=false, promo=SAVE20,  harga=100.000  → diskon 20%
// Path 4: member=false, promo=VIP,     harga=100.000  → diskon 30%
// Path 5: member=false, promo=null,    harga=600.000  → diskon 5%

// Aturan sistem: Nilai mahasiswa harus antara 0 dan 100
function validateNilai(nilai) {
  if (nilai < 0 || nilai > 100) {
    throw new Error('Nilai harus antara 0 dan 100');
  }
  return true;
}

// BVA TEST CASES — Fokus pada BATAS nilai valid
const bvaTestCases = [
  { input: -1,  expected: 'ERROR',  alasan: 'Batas bawah - 1 (tepat di luar batas)' },
  { input: 0,   expected: 'VALID',  alasan: 'Batas bawah minimum (tepat di batas)' },
  { input: 1,   expected: 'VALID',  alasan: 'Batas bawah + 1 (tepat di dalam batas)' },
  { input: 50,  expected: 'VALID',  alasan: 'Nilai tengah (nominal)' },
  { input: 99,  expected: 'VALID',  alasan: 'Batas atas - 1 (tepat di dalam batas)' },
  { input: 100, expected: 'VALID',  alasan: 'Batas atas maksimum (tepat di batas)' },
  { input: 101, expected: 'ERROR',  alasan: 'Batas atas + 1 (tepat di luar batas)' },
];

